inlineScript.scriptBlock:
//get doc id for the uploaded doc
this.addDocId = function (uploadResponse) {
	var parser = null;
	var xmlDoc = null;
	var output = null;
	if (window.DOMParser) {
		parser = new DOMParser();
		xmlDoc = parser.parseFromString(uploadResponse, "text/xml");
	} // Internet Explorer
	else {
		xmlDoc = new ActiveXObject("Microsoft.XMLDOM");
		xmlDoc.async = false;
		xmlDoc.loadXML(uploadResponse);
	}
	output = xmlDoc.querySelector("output");
	var docId = String(output.textContent.trim());
	console.log("<<Doc ID>> ",docId);
	this.callUpdateEcm(docId);
};

//call service to update doc prop
this.callUpdateEcm = function (docId) {
	var ecmProp = this.context.options.ECMProperties.get("value").get("defaultProperties").items;

	var callInput = JSON.stringify(ecmProp) + "&&" + docId;
//	console.clear();
	console.log("<<UpdateDocumentProperties Inputs>> ",callInput);
	this.ui.get("UpdateDocumentProperties").execute(callInput);
};

this.refreshECMList = function () {
	var elm = this.ui.get("ECM_Document_List1");
	if (elm) elm.refresh();
	console.log("<<UpdateDocumentProperties DONE>>");
};

