this.visControl = function  () {

	if (this.context.options.canCreate.get("value") == true) {
		this.ui.get("Table").setEnabled(true);
		this.ui.get("Button1").setVisible(true,true);
	}else{
		this.ui.get("Table").setEnabled(false);
		this.ui.get("Button1").setVisible(false,false);
	}
	
	
}
this.setCMISquery = function  () {
	var parent=this.context.options.parentPath;
	var query ="SELECT * FROM cmis:Document WHERE IN_TREE('"+parent+"')";
	this.context.options.cmisQuery.set("value", query);
}
